if (options.TryGetTypeInfo<Person>(out JsonTypeInfo<Person>? info))
{
    Console.WriteLine($"TryGetTypeInfo<Person> succeeded: {info!.Type.Name}");
}

// Now try a type that has NO resolver configured (source-gen-only options)
var restrictedOptions = new JsonSerializerOptions
{
    TypeInfoResolver = null // no resolver at all
};
restrictedOptions.MakeReadOnly();

if (restrictedOptions.TryGetTypeInfo<Person>(out JsonTypeInfo<Person>? missing))
{
    Console.WriteLine($"Unexpectedly resolved: {missing!.Type.Name}");
}
else
{
    Console.WriteLine("TryGetTypeInfo<Person> returned false — no metadata available (no exception thrown).");
}

public record Person(string Name, int Age);
